/*
 * Chat plugins for Castiello et al. (2026) Experiment 3, with replies generated by the chat
 * service (server/) through ChatClient (src/chat-client.js).
 *
 * jsPsychChatSetup  sends the BFI answers to the service, which assigns the two bots. Shows
 *                   "Setting up your chats…"; retries on its own, then offers Try again.
 * jsPsychLiveChat   one chat with one bot. The bot speaks first: the page asks for the opener
 *                   (hidden message 0), then bot 1, participant 2, bot 3, ... Every message from
 *                   either side is one turn; the chat ends after `total_messages`.
 *
 * The trial data hold counts and timings only. The text of the chat is kept by the service
 * (and exported to the private transcripts file), never in the jsPsych data.
 */
var jsPsychChatSetup = (function (jspsych) {
  "use strict";

  const info = {
    name: "chat-setup",
    version: "1.0.0",
    parameters: {
      client: { type: jspsych.ParameterType.OBJECT, default: null },
      get_answers: { type: jspsych.ParameterType.FUNCTION, default: () => ({}) },
      force: { type: jspsych.ParameterType.OBJECT, default: null },
      auto_retries: { type: jspsych.ParameterType.INT, default: 2 },
    },
    data: {
      setup_ok: { type: jspsych.ParameterType.BOOL },
      setup_attempts: { type: jspsych.ParameterType.INT },
      setup_error: { type: jspsych.ParameterType.STRING },
    },
  };

  class ChatSetupPlugin {
    constructor(jsPsych) {
      this.jsPsych = jsPsych;
    }

    trial(display_element, trial) {
      return new Promise((resolve) => {
        let attempts = 0;
        display_element.innerHTML = "";
        const box = document.createElement("div");
        box.className = "instructions chat-setup";
        const status = document.createElement("p");
        status.className = "chat-setup-status";
        box.appendChild(status);
        display_element.appendChild(box);

        const buttons = document.createElement("div");
        buttons.className = "chat-end";
        const button = (label, cls, onclick) => {
          const b = document.createElement("button");
          b.type = "button";
          b.className = "jspsych-btn " + cls;
          b.textContent = label;
          b.onclick = onclick;
          buttons.appendChild(b);
        };

        const done = (ok, error) => {
          display_element.innerHTML = "";
          resolve({ setup_ok: ok, setup_attempts: attempts, setup_error: error || null });
        };

        const attempt = async () => {
          buttons.innerHTML = "";
          buttons.remove();
          status.textContent = "Setting up your chats…";
          for (;;) {
            attempts += 1;
            try {
              await trial.client.startSession(trial.get_answers(), trial.force);
              return done(true);
            } catch (e) {
              const retryable = e && e.retryable;
              if (retryable && attempts % (trial.auto_retries + 1) !== 0) {
                await new Promise((r) => setTimeout(r, 1500 * attempts));
                continue;
              }
              status.textContent = retryable
                ? "We could not set up your chats. Please check your internet connection and try again."
                : "Something went wrong while setting up your chats, so the study cannot continue.";
              if (retryable) button("Try again", "chat-retry", attempt);
              button("Leave the study", "chat-leave", () => done(false, (e && e.code) || "error"));
              box.appendChild(buttons);
              return;
            }
          }
        };
        attempt();
      });
    }
  }
  ChatSetupPlugin.info = info;
  return ChatSetupPlugin;
})(jsPsychModule);

var jsPsychLiveChat = (function (jspsych) {
  "use strict";

  const info = {
    name: "live-chat",
    version: "1.0.0",
    parameters: {
      chat_index: { type: jspsych.ParameterType.INT, default: 1 },
      bot_name: { type: jspsych.ParameterType.STRING, default: "" },
      total_messages: { type: jspsych.ParameterType.INT, default: 24 },
      max_chars: { type: jspsych.ParameterType.INT, default: 1000 },
      client: { type: jspsych.ParameterType.OBJECT, default: null },
      // After this long without a reply, the status line says the reply is taking a while.
      // Live replies take several seconds (about 12 s for an opener and 6 s for a reply in the first
      // synthetic test), so the "still writing" note only appears after a longer wait.
      slow_after_ms: { type: jspsych.ParameterType.INT, default: 20000 },
      // After this many failed tries at the same message, offer to leave the study.
      failures_before_leave: { type: jspsych.ParameterType.INT, default: 3 },
    },
    data: {
      chat_index: { type: jspsych.ParameterType.INT },
      bot_name: { type: jspsych.ParameterType.STRING },
      n_messages: { type: jspsych.ParameterType.INT },
      n_participant_messages: { type: jspsych.ParameterType.INT },
      n_bot_messages: { type: jspsych.ParameterType.INT },
      participant_chars: { type: jspsych.ParameterType.INT },
      n_failed_requests: { type: jspsych.ParameterType.INT },
      n_retries: { type: jspsych.ParameterType.INT },
      ended_reason: { type: jspsych.ParameterType.STRING },
      chat_started_at: { type: jspsych.ParameterType.STRING },
      chat_ended_at: { type: jspsych.ParameterType.STRING },
      duration_ms: { type: jspsych.ParameterType.INT },
    },
  };

  function el(tag, cls, text) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text; // never innerHTML: the text comes from people and a model
    return e;
  }

  class LiveChatPlugin {
    constructor(jsPsych) {
      this.jsPsych = jsPsych;
    }

    trial(display_element, trial) {
      return new Promise((resolve) => {
        const started = new Date();
        const name = trial.bot_name;
        const counts = { participant: 0, bot: 0, chars: 0, failed: 0, retries: 0 };
        let lastSeq = 0;       // the last message shown (the hidden opener request is 0)
        let busy = false;      // a request is in flight or waiting for "Try again"
        let finished = false;
        let failuresHere = 0;  // consecutive failures for the current message
        let slowTimer = null;

        display_element.innerHTML = "";
        const box = el("div", "chat");
        box.dataset.chatIndex = String(trial.chat_index);
        const header = el("div", "chat-header", "Chat with " + name);
        const counter = el("div", "chat-counter");
        const log = el("div", "chat-log");
        log.setAttribute("aria-live", "polite");
        const status = el("div", "chat-status");
        status.setAttribute("role", "status"); // announced by screen readers
        // While a reply is being generated: a highlighted line with animated dots, outside the
        // message log (so it is never mistaken for a message or counted).
        const setStatus = (text, waiting) => {
          status.className = waiting ? "chat-status chat-waiting" : "chat-status";
          status.textContent = text;
          if (waiting) status.appendChild(el("span", "chat-dots"));
        };
        const actions = el("div", "chat-actions");
        const form = el("form", "chat-form");
        const input = el("textarea", "chat-input");
        input.rows = 2;
        input.maxLength = trial.max_chars;
        input.placeholder = "Type your message";
        input.setAttribute("aria-label", "Your message");
        const send = el("button", "jspsych-btn chat-send", "Send");
        send.type = "submit";
        form.append(input, send);
        box.append(header, counter, log, status, actions, form);
        display_element.appendChild(box);

        const updateCounter = () => {
          counter.textContent = "Message " + Math.min(lastSeq + 1, trial.total_messages) + " of " + trial.total_messages;
        };
        const setInputEnabled = (on) => {
          input.disabled = !on;
          send.disabled = !on;
          if (on) input.focus();
        };
        const addBubble = (from, text, seq) => {
          const b = el("div", "chat-msg chat-" + from, text);
          b.dataset.seq = String(seq);
          b.dataset.from = from;
          log.appendChild(b);
          log.scrollTop = log.scrollHeight;
        };

        const finish = (reason) => {
          if (finished) return;
          finished = true;
          clearTimeout(slowTimer);
          const ended = new Date();
          display_element.innerHTML = "";
          resolve({
            chat_index: trial.chat_index,
            bot_name: name,
            n_messages: counts.participant + counts.bot,
            n_participant_messages: counts.participant,
            n_bot_messages: counts.bot,
            participant_chars: counts.chars,
            n_failed_requests: counts.failed,
            n_retries: counts.retries,
            ended_reason: reason,
            chat_started_at: started.toISOString(),
            chat_ended_at: ended.toISOString(),
            duration_ms: ended - started,
          });
        };

        const endOfChat = () => {
          form.remove();
          actions.innerHTML = "";
          status.textContent = "";
          counter.textContent = "Message " + trial.total_messages + " of " + trial.total_messages;
          const note = el("div", "chat-end");
          note.appendChild(el("p", null, "Your chat with " + name + " has ended."));
          const next = el("button", "jspsych-btn chat-continue", "Continue");
          next.type = "button";
          next.onclick = () => finish("complete");
          note.appendChild(next);
          box.appendChild(note);
          next.focus();
        };

        const actionButton = (label, cls, onclick) => {
          const b = el("button", "jspsych-btn " + cls, label);
          b.type = "button";
          b.onclick = onclick;
          actions.appendChild(b);
        };

        // Send one participant message (or the opener request) and show the reply. A failed
        // request leaves the participant's message on screen and offers "Try again", which
        // repeats exactly the same request; the service never answers the same message twice.
        const request = (seq, text) => {
          busy = true;
          setInputEnabled(false);
          actions.innerHTML = "";
          setStatus(seq === 0 ? name + " is writing the first message" : name + " is writing a reply", true);
          clearTimeout(slowTimer);
          slowTimer = setTimeout(() => { setStatus(name + " is still writing. This is taking longer than usual.", true); }, trial.slow_after_ms);
          trial.client.turn(trial.chat_index, seq, text).then((res) => {
            clearTimeout(slowTimer);
            if (finished) return;
            failuresHere = 0;
            busy = false;
            setStatus("", false);
            if (res.reply) {
              lastSeq = res.reply.seq;
              counts.bot += 1;
              addBubble("bot", String(res.reply.text), lastSeq);
            }
            updateCounter();
            if (res.done) endOfChat();
            else setInputEnabled(true);
          }, (err) => {
            clearTimeout(slowTimer);
            if (finished) return;
            counts.failed += 1;
            failuresHere += 1;
            setStatus("", false);
            if (err && err.retryable) {
              status.textContent = name + "'s reply didn't arrive.";
              actionButton("Try again", "chat-retry", () => { counts.retries += 1; request(seq, text); });
              if (failuresHere >= trial.failures_before_leave) {
                status.textContent = name + "'s reply didn't arrive. You can try again, or leave the study if this keeps happening.";
                actionButton("Leave the study", "chat-leave", () => finish("failed"));
              }
            } else {
              status.textContent = "Something went wrong with this chat, so it cannot continue.";
              actionButton("Leave the study", "chat-leave", () => finish("failed"));
            }
          });
        };

        form.addEventListener("submit", (ev) => {
          ev.preventDefault();
          const text = input.value.trim();
          if (busy || finished || !text) return;
          const seq = lastSeq + 1;
          lastSeq = seq;
          counts.participant += 1;
          counts.chars += text.length;
          addBubble("participant", text, seq);
          input.value = "";
          updateCounter();
          request(seq, text);
        });
        // Enter sends; Shift+Enter starts a new line.
        input.addEventListener("keydown", (ev) => {
          if (ev.key === "Enter" && !ev.shiftKey) {
            ev.preventDefault();
            form.requestSubmit();
          }
        });

        updateCounter();
        request(0, "");
      });
    }
  }
  LiveChatPlugin.info = info;
  return LiveChatPlugin;
})(jsPsychModule);
